    padding: 0.4rem 1rem;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.8rem;
    margin-bottom: 0.5rem;
}

.load-more-btn:hover {
    background: #dee2e6;
}

.loading-indicator {
    text-align: center;
