    cursor: pointer;
    padding: 0.2rem 0.4rem;
    border-radius: 3px;
    font-size: 0.85rem;
}

.action-btn:hover {
    background: #e9ecef;
}

.emoji-picker {
    position: absolute;
    top: -2.2rem;
