    background: white;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    padding: 0.3rem;
    display: flex;
    gap: 0.15rem;
    box-shadow: 0 2px 8px rgba(0,0,0,0.12);
    z-index: 10;
}

.emoji-btn {
    background: none;
    border: none;
    cursor: pointer;
    font-size: 1.1rem;
    padding: 0.2rem;
    border-radius: 3px;
}

.emoji-btn:hover {
    background: #e9ecef;
}

.message-input-area {
    display: flex;
    gap: 0.5rem;
    padding: 0.75rem 1.25rem;
    border-top: 1px solid #dee2e6;
    background: white;
}

.message-input {
    flex: 1;
    resize: none;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    padding: 0.5rem 0.75rem;
    font-size: 0.9rem;
